INSERT INTO public."Column_Catalog" (
    table_schema, table_name, column_name, ordinal_position, data_type,
    is_nullable, default_expression, is_primary_key, definition,
    source_column_or_expression, unit, null_rule, source_code_paths,
    documentation_status
)
SELECT columns.table_schema, columns.table_name, columns.column_name, columns.ordinal_position,
       columns.data_type, false, columns.column_default, columns.column_name IN ('method_id', 'engine_version'),
       CASE columns.column_name
        WHEN 'method_id' THEN 'Registered method id (research_plan/v2 method_id).'
        WHEN 'engine_version' THEN 'Version of the statistical engines the row describes.'
        WHEN 'library_version' THEN 'Version of the research library content.'
        WHEN 'method_family' THEN 'One of the five method families; an agreement between angles needs two families.'
        WHEN 'question_shape' THEN 'The question the method answers, in general form.'
        WHEN 'input_roles' THEN 'JSON array of input roles (role, type, required, meaning); logical roles, not column names.'
        WHEN 'required_parameters' THEN 'JSON array of the parameters an angle of this method must set, with their rules.'
        WHEN 'optional_parameters' THEN 'JSON array of the parameters an angle may set, with their rules.'
        WHEN 'data_requirements' THEN 'JSON object: entity column, label constancy, outcome kind, minimum entities per date and notes; the feasibility check enforces them.'
        WHEN 'common_requirements' THEN 'JSON array of the requirements every method shares (one row per entity and date, declarations, forward returns).'
        WHEN 'sample_unit' THEN 'Unit of the effective sample: DATES, ENTITIES or DATES_AUTOCORRELATION_ADJUSTED.'
        WHEN 'secondary_checks' THEN 'JSON array of checks that must pass for SUPPORTED (for example monotonicity).'
        WHEN 'decision_rules_ref' THEN 'Where the status rules are defined; enforcement is research_engines.decide in code.'
        WHEN 'interpretation' THEN 'What the method''s estimate means.'
        WHEN 'misuse_warning' THEN 'How the result is commonly misread.'
        WHEN 'example_question' THEN 'An illustrative question the method answers.'
        WHEN 'library_sha256' THEN 'Hash of the whole library; market-ai-orc enables multi-angle research only when it equals the sandbox''s and its own.'
        WHEN 'is_active' THEN 'Whether the method is offered to the model.'
        WHEN 'created_at' THEN 'Row creation time.'
        WHEN 'updated_at' THEN 'Last update time.'
       END,
       'app/research_library.py (rows())', NULL, 'NULL is not permitted.',
       ARRAY['database/migrations/20260930_001_create_ai_research_library.sql'], 'VERIFIED'
FROM information_schema.columns AS columns
WHERE columns.table_schema = 'public' AND columns.table_name = 'AI_research_library';

DO $verify$
BEGIN
    IF (SELECT count(*) FROM public."AI_research_library" WHERE is_active AND library_sha256 = 'b4f10f55fd1ad4919be0eeca74b64dae955d46148fa027ec4a70ed9a01e17058') <> 8
       OR (SELECT count(DISTINCT method_family) FROM public."AI_research_library") <> 5 THEN
        RAISE EXCEPTION 'Expected 8 active research library rows with the library hash and five families';
    END IF;
    IF (SELECT count(*) FROM public."Column_Catalog" WHERE table_name = 'AI_research_library'
          AND definition IS NOT NULL) <> 20
       OR NOT EXISTS (SELECT 1 FROM public."Table_Catalog" WHERE table_name = 'AI_research_library') THEN
        RAISE EXCEPTION 'AI_research_library lacks its Table_Catalog / Column_Catalog definitions';
    END IF;
    IF NOT has_table_privilege('market_ai_catalog_reader', 'public."AI_research_library"', 'SELECT')
       OR has_table_privilege('market_ai_catalog_reader', 'public."AI_research_library"', 'INSERT,UPDATE,DELETE') THEN
        RAISE EXCEPTION 'market_ai_catalog_reader privileges do not match the read-only contract';
    END IF;
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'market_ai_sql_reader')
       AND has_table_privilege('market_ai_sql_reader', 'public."AI_research_library"', 'SELECT') THEN
        RAISE EXCEPTION 'The SQL Governor unexpectedly reads the research library';
    END IF;
END
$verify$;
COMMIT;
